// Six tools, one gate. This is the whole reason each tool re-enters the
// workflow instead of calling Bright Data straight from an HTTP Request Tool.
//
// An MCP client is a loop. Ask Claude one question and it may search three
// times, read two pages, then search again to check itself - and tomorrow it
// starts from nothing. Every one of those is a paid Bright Data request, and a
// Bing web search measured 40.5 seconds, so the repeats cost waiting as well as
// money.
//
// State lives in the workflow's own static data, which n8n keeps between
// executions: the cache, and one call counter per day.
//
// The caveat is in the red sticky and worth repeating here. n8n only writes
// static data back for production executions. Run this from the canvas and the
// store is read but the writes are dropped, so a manual test always reports a
// miss. That is n8n behaving as documented, not the cache failing.

const cfg = $('Limits').first().json;
const req = $('Tool Call').first().json || {};

const store = $getWorkflowStaticData('global');
if (!store.cache) store.cache = {};
if (!store.usage) store.usage = {};

const now = Date.now();
const today = new Date(now).toISOString().slice(0, 10);

// Yesterday's counter is never read again. Left alone it adds a key a day to an
// object that is serialised and written back on every single tool call.
for (const day of Object.keys(store.usage)) {
  if (day !== today) delete store.usage[day];
}
const used = store.usage[today] || 0;
const budget = Number(cfg.daily_call_budget) || 200;

const ROUTES = {
  search_web: 'google',
  google_ai_overview: 'google',
  related_questions: 'google',
  search_bing: 'bing',
  search_news: 'news',
  read_page: 'page'
};

const tool = String(req.tool || '').trim();
const route = ROUTES[tool];
const query = String(req.query || '').trim();
const url = String(req.url || '').trim();
const country = (String(req.country || '').trim() || 'us').toLowerCase();

// A refusal is an answer, not a failure. A tool that throws hands the model a
// stack trace and no way forward; a tool that names the argument that was wrong
// gets a corrected call back on the next turn.
function refuse(note) {
  return [{ json: { action: 'refused', tool: tool, note: note } }];
}

if (!route) {
  return refuse('Unknown tool "' + tool + '". Available: ' +
    Object.keys(ROUTES).join(', ') + '.');
}
if (route === 'page') {
  if (!/^https?:\/\/\S+$/i.test(url)) {
    return refuse('read_page needs a full url starting with http:// or https://. ' +
      'Received: "' + url + '".');
  }
} else if (query.length < 2) {
  return refuse('The query argument was empty. Send the search terms as plain ' +
    'text, for example: best running shoes 2026.');
}
if (route === 'google' && !/^[a-z]{2}$/.test(country)) {
  return refuse('country must be a two letter lowercase code such as us, uk or ' +
    'de. Received: "' + country + '".');
}
if (used >= budget) {
  return refuse('The daily budget of ' + budget + ' Bright Data calls is spent. ' +
    'It resets at 00:00 UTC. Answer from what you already have, or ask whoever ' +
    'runs this server to raise daily_call_budget in the Limits node.');
}

// News ages out faster than anything else here, so it gets its own shorter life
// rather than sharing one TTL with a page read.
const ttlMinutes = route === 'news'
  ? (Number(cfg.news_cache_minutes) || 15)
  : (Number(cfg.cache_minutes) || 60);

// Country is part of the key. The same query run from us and from de is two
// different result sets, and serving one for the other is the kind of bug that
// surfaces a week later in a ranking report.
const subject = route === 'page' ? url : query.toLowerCase();
const key = [tool, subject, route === 'page' ? '' : country].join('|');

const hit = store.cache[key];
if (hit && hit.at && now - hit.at < ttlMinutes * 60000) {
  return [{ json: {
    action: 'cached',
    tool: tool, route: route, query: query, country: country, url: url,
    cache_key: key,
    cache_age_seconds: Math.round((now - hit.at) / 1000),
    result: hit.payload
  } }];
}

return [{ json: {
  action: 'fetch',
  tool: tool, route: route, query: query, country: country, url: url,
  cache_key: key,
  ttl_minutes: ttlMinutes
} }];

// Two ways to answer without spending a request: the cache already had it, or
// the call should not be made at all. Both leave here shaped like a normal
// answer, because a model handles a field it understands better than an error
// it does not.

// single-item input: one tool call, one decision.
const d = $input.first().json;

if (d.action === 'cached') {
  return [{ json: Object.assign({}, d.result, {
    cached: true,
    cache_age_seconds: d.cache_age_seconds
  }) }];
}

return [{ json: { ok: false, tool: d.tool, error: d.note } }];

// One shaper for all four responses, because they fail in the same ways and a
// model needs them to succeed and fail the same way too.
//
// Bright Data answers a wrong zone, an empty balance and a rate limit with HTTP
// 200 and an error body, and under load it sometimes answers 200 with no body
// at all. Read naively, all three look like "nothing found". A tool that
// reports no results when the truth is "your zone name is wrong" costs an agent
// the rest of its turn rewording a query that was never the problem.

// single-item input: one tool call makes one request, and only the branch that
// handled it reaches this node.
const raw = $input.first().json;
const req = $('Check Cache And Budget').first().json;
const cfg = $('Limits').first().json;
const maxResults = Number(cfg.max_results) || 10;
const maxChars = Number(cfg.max_page_chars) || 12000;

function fail(message) {
  return [{ json: { ok: false, tool: req.tool, error: message } }];
}

let payload = raw.body != null ? raw.body : (raw.data != null ? raw.data : raw);
if (typeof payload === 'string') {
  if (!payload.trim()) {
    return fail('Bright Data returned an empty response. This one is transient - ' +
      'call the tool once more.');
  }
  if (req.route !== 'page') {
    try {
      payload = JSON.parse(payload);
    } catch (e) {
      // A wrong zone is answered with HTTP 400 and one plain sentence - `zone
      // "no_such_zone" not found` - rather than with JSON. neverError hides the
      // status code, so that sentence is the only diagnosis there is. Passing it
      // through verbatim beats any message written here in advance.
      return fail('Bright Data did not return search results. It said: ' +
        payload.trim().slice(0, 200));
    }
  }
}
if (payload && typeof payload === 'object' && payload.error) {
  return fail('Bright Data rejected the request: ' + String(payload.error) +
    ' Check the zone names in the Limits node and the account balance.');
}

// Google puts screen-reader text straight into the titles and snippets it
// returns. Left in, the model reads "Opens in new tab." as part of a page title.
const NOISE = /(Go to product viewer dialog for this item\.|Opens in new tab\.|Read more)/g;
function clean(s) {
  return String(s == null ? '' : s).replace(NOISE, '').replace(/\s+/g, ' ').trim();
}

// About 94% of a measured 105KB Google response was base64 image data, and a
// page read can carry the same thing inline - invisible to the model, billed to
// its context window.
//
// Markdown image links are the same problem wearing a URL. The n8n docs page
// measured on 2026-08-17 spent about 3,000 of its 26,088 characters on one
// favicon URL repeated six times in the header and nav, none of which a text
// tool can look at. Alt text is kept where there is any, because that part does
// carry meaning.
function stripImages(s) {
  return String(s)
    .replace(/data:[a-z]+\/[a-z0-9.+-]+;base64,[A-Za-z0-9+\/=\s]{40,}/gi, '[image]')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1');
}

// Nav bars survive the conversion to markdown as the same handful of lines
// repeated at the top and again at the bottom. Consecutive duplicates are safe
// to drop; a repeat further down the page might be real content, so this only
// looks at the line before.
function dropRepeats(s) {
  const kept = [];
  for (const line of String(s).split('\n')) {
    const t = line.trim();
    if (t && kept.length && kept[kept.length - 1].trim() === t) continue;
    kept.push(line);
  }
  return kept.join('\n');
}

// Google hands back the same reference twice often enough to matter - two of
// two on the query measured on 2026-08-17 were the same Reddit thread. A model
// reads a repeat as corroboration, so this is worse than noise.
function dedupe(rows, key) {
  const seen = new Set();
  return rows.filter(function (r) {
    const k = String(r[key] || '');
    if (!k || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

// Some Google links arrive wrapped as google.com/url?...&url=<real>. Eight of
// eight references came back clean on the query measured on 2026-08-17, so this
// is a guard rather than the common case. The alternative is telling the model
// to unwrap URLs itself, which is a string operation it will sometimes skip.
function unwrap(link) {
  const s = String(link || '');
  const m = s.match(/[?&]url=([^&]+)/);
  if (!m) return s;
  let candidate = m[1];
  try {
    candidate = decodeURIComponent(candidate);
  } catch (e) {
    return s;
  }
  return /^https?:\/\//i.test(candidate) ? candidate : s;
}

function host(link) {
  const m = String(link || '').match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].replace(/^www\./, '') : '';
}

let out;

if (req.route === 'page') {
  const body = typeof payload === 'string' ? payload : String(payload.body || '');
  // Clean before truncating, so the character budget is spent on the page
  // rather than on its header.
  const md = dropRepeats(stripImages(body)).replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n').trim();
  if (!md) {
    return fail('The page came back empty. It may need a login, or unlocker_zone ' +
      'in the Limits node may be wrong.');
  }
  // A bad Web Unlocker zone fails the same way a bad SERP zone does: HTTP 400
  // and one sentence. There is no JSON to fail parsing down this branch, so
  // without this check that sentence goes to the model dressed up as the page.
  if (md.length < 200 &&
      /\b(not found|invalid|unauthorized|forbidden|denied|error)\b/i.test(md)) {
    return fail('Bright Data did not return the page. It said: ' + md.slice(0, 200));
  }
  const truncated = md.length > maxChars;
  out = {
    ok: true,
    tool: req.tool,
    url: req.url,
    characters: md.length,
    truncated: truncated,
    markdown: truncated
      ? md.slice(0, maxChars) + '\n\n[Truncated at ' + maxChars + ' characters. ' +
        'Raise max_page_chars in the Limits node to read more.]'
      : md
  };
} else if (req.tool === 'google_ai_overview') {
  const ov = payload.ai_overview || {};
  // texts is a list of objects, not of strings, and each one carries a `links`
  // array of Google shopping URLs. Forwarding it whole made this the largest
  // response of the six tools; the part worth reading is `snippet`.
  const answer = (ov.texts || [])
    .map(function (t) { return clean(typeof t === 'string' ? t : t.snippet); })
    .filter(Boolean)
    .join('\n\n');
  // References key the URL as `href`. Reading `link` gives undefined on every row.
  const sources = dedupe((ov.references || [])
    .map(function (r) { return { title: clean(r.title), link: unwrap(r.href || r.link) }; })
    .filter(function (r) { return r.link; }), 'link').slice(0, maxResults);
  out = { ok: true, tool: req.tool, query: req.query, country: req.country,
          answer: answer, sources: sources };
  if (!answer && !sources.length) {
    out.note = 'Google showed no AI Overview for this search. That is common on ' +
      'narrow or navigational queries - try search_web instead.';
  }
} else if (req.tool === 'related_questions') {
  const questions = (payload.people_also_ask || [])
    .map(function (r) { return clean(r.question); })
    .filter(function (q, i, all) { return q && all.indexOf(q) === i; })
    .slice(0, maxResults * 2);
  out = { ok: true, tool: req.tool, query: req.query, country: req.country,
          questions: questions };
} else if (req.route === 'news') {
  // Bing news rows carry no source field - the keys are created, image,
  // image_url, link, text and title. Selecting `source` returned undefined on
  // every row and the news reached the model unattributed, so the publisher
  // comes off the link instead.
  const news = dedupe((payload.news || []).map(function (r) {
    return {
      title: clean(r.title),
      snippet: clean(r.text),
      source: host(r.link),
      published: r.created,
      link: unwrap(r.link)
    };
  }).filter(function (r) { return r.link; }), 'link')
    .slice(0, maxResults)
    .map(function (r, i) { return Object.assign({ rank: i + 1 }, r); });
  out = { ok: true, tool: req.tool, query: req.query, results: news };
} else {
  const rows = dedupe((payload.organic || []).map(function (r, i) {
    return {
      rank: r.rank || i + 1,
      title: clean(r.title),
      link: unwrap(r.link),
      snippet: clean(r.description),
      source: clean(r.source || r.site_name) || host(r.link)
    };
  }).filter(function (r) { return r.link; }), 'link').slice(0, maxResults);
  out = { ok: true, tool: req.tool, query: req.query, results: rows };
  if (req.route === 'google') out.country = req.country;
  if (!rows.length) {
    out.note = 'No organic results came back for that query. Try fewer or ' +
      'broader terms.';
  }
}

return [{ json: out }];

// The cache is only worth having if it is bounded. This runs on every fresh
// call: it books the request against today's budget, stores the answer, then
// prunes - expired entries first, and oldest-first if the store is still over
// its cap. A cache that only grows is a memory leak with a friendly name, and
// this one is serialised and written back on every tool call.

// single-item input: one tool call, one shaped response.
const res = $input.first().json;
const req = $('Check Cache And Budget').first().json;
const cfg = $('Limits').first().json;

const store = $getWorkflowStaticData('global');
if (!store.cache) store.cache = {};
if (!store.usage) store.usage = {};

const now = Date.now();
const today = new Date(now).toISOString().slice(0, 10);

// Booked whether or not the answer was usable. Bright Data was called either
// way, so a budget that counted only successes would not cap spend.
store.usage[today] = (store.usage[today] || 0) + 1;

// Failures are deliberately not cached. Caching one transient empty response
// would keep serving it for the next hour.
if (res.ok) {
  store.cache[req.cache_key] = {
    at: now,
    ttl: (Number(req.ttl_minutes) || 60) * 60000,
    payload: res
  };
}

for (const k of Object.keys(store.cache)) {
  const entry = store.cache[k];
  if (!entry || !entry.at || now - entry.at > entry.ttl) delete store.cache[k];
}

const cap = Number(cfg.max_cache_entries) || 200;
const keys = Object.keys(store.cache);
if (keys.length > cap) {
  keys.sort(function (a, b) { return store.cache[a].at - store.cache[b].at; });
  for (const k of keys.slice(0, keys.length - cap)) delete store.cache[k];
}

return [{ json: res }];

// Everything converges here, so the sub-workflow has exactly one last node and
// every answer carries the same footer.
//
// The footer is the point. A model that can see it has six calls left today
// will stop looping on its own; discovering the cap as an error three calls
// later helps nobody.

const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const used = (store.usage || {})[today] || 0;
const budget = Number($('Limits').first().json.daily_call_budget) || 200;

return $input.all().map(function (item) {
  return { json: Object.assign({ cached: false }, item.json, {
    calls_used_today: used,
    calls_left_today: Math.max(0, budget - used)
  }) };
});
